{
  "name": "Harness weight validation {{weightRuleRun}}",
  "description": "Provider harness, rejected at create; deleted by the same row if a build accepts it.",
  "priority": {{weightRulePriority}},
  "cel_expression": "\"x-harness-weight-run\" in headers && headers[\"x-harness-weight-run\"] == \"{{weightRuleRun}}\"",
  "scope": "global",
  "targets": [
    {
      "provider": "openai",
      "model": "gpt-4o-mini",
      "weight": 1
    },
    {
      "provider": "openai",
      "model": "gpt-4o",
      "weight": 0
    }
  ]
}
